// JAH demo program — runnable with: node demo.js
// Record JAH-APX2-000011 — Worked example: mapping a river monitoring station
// Lineage trace: walks a derivation graph from an output back to its root sources.
'use strict';
var edges = [["daily-summary", "fused-temperature"], ["fused-temperature", "probe-a-readings"], ["fused-temperature", "probe-b-readings"], ["probe-a-readings", "calibration-cert-88"], ["daily-summary", "oxygen-average"], ["oxygen-average", "oxygen-readings"]];
var target = "daily-summary";
var parents = {};
edges.forEach(function (e2) { (parents[e2[0]] = parents[e2[0]] || []).push(e2[1]); });
var chain = [target]; var cur = target; var guard = 0;
while (parents[cur] && parents[cur].length && guard++ < 50) { cur = parents[cur][0]; chain.push(cur); }
console.log('target=' + target + ' lineage_depth=' + (chain.length - 1));
console.log('chain: ' + chain.join(' <- '));
var roots = chain.filter(function (x) { return !parents[x]; });
console.log('root_sources=' + roots.join(', '));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX2-000012 — Failure modes: calibration lapse and silent drift
// Uncertainty quantification: separates measured spread from model uncertainty.
'use strict';
var ms = [18.1, 18.3, 18.9, 19.4, 19.8, 20.1];
var modelVar = 0.02;
var mean = ms.reduce(function (a, b) { return a + b; }, 0) / ms.length;
var mvar = ms.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / ms.length;
var total = mvar + modelVar;
console.log('n=' + ms.length + ' mean=' + mean.toFixed(3));
console.log('measured_variance=' + mvar.toFixed(4) + ' (' + (100 * mvar / total).toFixed(1) + '%)');
console.log('model_variance=' + modelVar.toFixed(4) + ' (' + (100 * modelVar / total).toFixed(1) + '%)');
console.log('total_uncertainty_stddev=' + Math.sqrt(total).toFixed(4));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX2-000013 — Scaling: from one station to a sensor planet
// Monte Carlo workload simulation: latency distribution under a synthetic load model.
'use strict';
var n = 2000, seed = 7;
var a = seed >>> 0;
function rnd() { a = (Math.imul(a, 1664525) + 1013904223) >>> 0; return a / 4294967296; }
var sum = 0, sum2 = 0;
for (var i = 0; i < n; i++) { var x = 2 + rnd() * 88; sum += x; sum2 += x * x; }
var mean = sum / n, variance = sum2 / n - mean * mean;
console.log('samples=' + n + ' mean_ms=' + mean.toFixed(2) + ' stddev_ms=' + Math.sqrt(variance).toFixed(2));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX2-000014 — Security: protecting the chain of custody
// Machine-checked verification: each claimed identity is recomputed and checked.
'use strict';
var checks = [{"expr": "21.4+0.2", "expect": 21.6}, {"expr": "18.2*2-18.2", "expect": 18.2}, {"expr": "100/4", "expect": 25}];
var fails = 0;
checks.forEach(function (ch) {
  var got = eval(ch.expr);
  var ok = Math.abs(got - ch.expect) < 1e-9;
  if (!ok) fails++;
  console.log((ok ? 'PASS' : 'FAIL') + '  ' + ch.expr + ' = ' + got + ' (expected ' + ch.expect + ')');
});
console.log('proof_check: ' + (checks.length - fails) + '/' + checks.length + ' identities verified');

// JAH demo program — runnable with: node demo.js
// Record JAH-APX2-000015 — Compounded integration and acceptance suite
// Evidence constellation: every conclusion scored from supporting and contesting sources.
'use strict';
var claims = [{"claim": "fused temperature within 0.1C of ground truth", "sources": [{"s": "fixture scorer", "stance": "supports", "weight": 2.0}, {"s": "manual audit", "stance": "supports", "weight": 1.0}]}, {"claim": "all quarantined readings lacked calibration", "sources": [{"s": "quarantine log", "stance": "supports", "weight": 1.5}, {"s": "spot check", "stance": "contests", "weight": 0.5}]}];
claims.forEach(function (cl) {
  var sup = 0, con = 0;
  cl.sources.forEach(function (s) { if (s.stance === 'supports') sup += s.weight; else con += s.weight; });
  var net = sup - con; var total = sup + con;
  var verdict = net > 0 && total >= 2 ? 'SUPPORTED' : (con > sup ? 'CONTESTED' : 'UNCERTAIN');
  console.log('claim: ' + cl.claim);
  console.log('  support=' + sup.toFixed(1) + ' contest=' + con.toFixed(1) + ' verdict=' + verdict);
});
